  for(let y=minY;y<=maxY;y++)for(let x=minX;x<=maxX;x++){const px=x+.5,py=y+.5,wa=((b[0]-px)*(c[1]-py)-(b[1]-py)*(c[0]-px))*inv,wb=((c[0]-px)*(a[1]-py)-(c[1]-py)*(a[0]-px))*inv,wc=1-wa-wb;if(wa<0||wb<0||wc<0)continue;const iz=wa*a[2]+wb*b[2]+wc*c[2],z=1/iz,at=y*W+x;if(z>=depth[at])continue;let r=255,g=255,bl=255,opacity=alpha;if(tex){let u=(wa*a[3]+wb*b[3]+wc*c[3])*z,v=(wa*a[4]+wb*b[4]+wc*c[4])*z;if(tm){const uu=tm[0]*u+tm[3]*v+tm[6];v=tm[1]*u+tm[4]*v+tm[7];u=uu;}u=map.wrapS===THREE.RepeatWrapping?u-Math.floor(u):Math.max(0,Math.min(.99999,u));v=map.wrapT===THREE.RepeatWrapping?v-Math.floor(v):Math.max(0,Math.min(.99999,v));if(map.flipY)v=1-v;const tx=Math.min(tex.w-1,Math.floor(u*tex.w)),ty=Math.min(tex.h-1,Math.floor(v*tex.h)),ti=(ty*tex.w+tx)*4;r=tex.data[ti];g=tex.data[ti+1];bl=tex.data[ti+2];opacity*=tex.data[ti+3]/255;if(alphaTex){const ai=(Math.min(alphaTex.h-1,Math.floor(v*alphaTex.h))*alphaTex.w+Math.min(alphaTex.w-1,Math.floor(u*alphaTex.w)))*4;opacity*=alphaTex.data[ai+1]/255;}}if(opacity<(m.alphaTest||.02))continue;const light=this.unlit?1:lightFlat,fog=Math.min(.88,Math.max(0,(z-28)/140));r=r*Math.sqrt(tint[0])*light*(1-fog)+this.fog[0]*fog;g=g*Math.sqrt(tint[1])*light*(1-fog)+this.fog[1]*fog;bl=bl*Math.sqrt(tint[2])*light*(1-fog)+this.fog[2]*fog;const k=at*4;if(opacity<.98){out[k]=out[k]*(1-opacity)+r*opacity;out[k+1]=out[k+1]*(1-opacity)+g*opacity;out[k+2]=out[k+2]*(1-opacity)+bl*opacity;}else{out[k]=r;out[k+1]=g;out[k+2]=bl;}if(m.depthWrite)depth[at]=z;}
